        path,
        GENERIC_READ,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        nullptr,
        OPEN_EXISTING,
        FILE_ATTRIBUTE_NORMAL,
        nullptr);

    if (hFile == INVALID_HANDLE_VALUE) return false;

    LARGE_INTEGER fileSizeLI;
    if (!GetFileSizeEx(hFile, &fileSizeLI)) {
        CloseHandle(hFile);
        return false;
    }

    SIZE_T fileSize = static_cast<SIZE_T>(fileSizeLI.QuadPart);
    if (fileSize == 0) {
        CloseHandle(hFile);
        return false;
    }

    BYTE* base = reinterpret_cast<BYTE*>(VirtualAlloc(
        nullptr,
        fileSize,
        MEM_COMMIT | MEM_RESERVE,
        PAGE_READWRITE));

    if (!base) {
        CloseHandle(hFile);
        return false;
    }

    SIZE_T totalRead = 0;
    const SIZE_T kChunkSize = 64 * 1024;

    while (totalRead < fileSize) {
        SIZE_T remaining = fileSize - totalRead;
        DWORD bytesToRead = static_cast<DWORD>(remaining > kChunkSize ? kChunkSize : remaining);
        DWORD bytesRead = 0;

        BOOL ok = ReadFile(
            hFile,
            base + totalRead,
            bytesToRead,
            &bytesRead,
            nullptr);

        if (!ok || bytesRead == 0) {
            VirtualFree(base, 0, MEM_RELEASE);
            CloseHandle(hFile);
            return false;
        }

        totalRead += static_cast<SIZE_T>(bytesRead);
    }

    CloseHandle(hFile);

    *outBase = base;
    *outSize = fileSize;
    return true;
